import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Regolare il contrasto richiede solo pochi minuti. Carichi la foto, trascini un cursore, controlli le luci e le ombre e scarichi la versione più decisa.</p>\n<p>Questa guida pratica ti accompagna in tutto il procedimento, passo passo. Copre il cursore, i preset rapidi, le modalità di confronto e le impostazioni di esportazione che mantengono il risultato naturale.</p>\n<p>Alla fine saprai sistemare un paesaggio piatto, ammorbidire un ritratto duro o rendere più nitido uno screenshot spento su qualsiasi dispositivo. Conserva la foto originale finché non hai controllato il risultato.</p>\n<h2 id=\"before-you-start\">Prima di iniziare: fai una diagnosi della foto</h2>\n<p>Guarda la foto prima di aprire lo strumento. È piatta e grigia, dura con ombre profonde o con un’estensione corretta? La risposta ti dice in quale direzione spostare il cursore.</p>\n<p>Una foto piatta ha bisogno di una spinta positiva, del 10-20%. Una foto dura ha bisogno di uno spostamento negativo, del 10-20%, per ammorbidire gli estremi.</p>\n<p>Controlla se la foto è anche troppo scura o troppo chiara. Una foto scura e piatta ha bisogno prima di luminosità, perché il contrasto da solo non può sistemare il livello.</p>\n<p>Apri lo strumento <a href=\"/it/regola-contrasto-immagine/\">Regola contrasto immagine</a> nel browser. Tutto funziona in locale, quindi la tua foto non viene mai caricata su un server.</p>\n<h2 id=\"step-by-step\">Regola il contrasto in cinque passaggi</h2>\n<p>Il procedimento è lo stesso per una foto, uno screenshot o un documento scansionato. Carica, regola, confronta, esporta e verifica il file scaricato.</p>\n<p>Prenditi il tempo necessario per il cursore. Piccoli spostamenti fanno una grande differenza, e l’anteprima ti mostra esattamente quando la foto sembra giusta.</p>\n<ol>\n<li>Carica l’immagine trascinandola nella zona di caricamento, scegliendola dal dispositivo oppure incollando uno screenshot con Ctrl+V.</li>\n<li>Trascina il cursore Livello di contrasto a destra per aumentare il contrasto o a sinistra per diminuirlo, guardando l’anteprima in tempo reale.</li>\n<li>Prova un preset rapido per un test in un clic, poi rifinisci con il cursore se il risultato è vicino ma non del tutto giusto.</li>\n<li>Usa le modalità di confronto per controllare luci e ombre rispetto all’originale prima di scaricare.</li>\n<li>Scegli il formato di esportazione e la qualità, poi clicca Scarica per salvare l’immagine modificata.</li>\n</ol>\n<p>Apri il file scaricato una volta prima di usarlo. Conferma che la foto sembri decisa senza perdere dettagli nelle zone chiare o scure.</p>\n<h2 id=\"using-the-slider\">Usare il cursore del contrasto</h2>\n<p>Il cursore va da valori negativi a valori positivi, con lo zero che significa nessun cambiamento. Spostandolo a destra si aumenta il contrasto, spostandolo a sinistra lo si diminuisce.</p>\n<p>Trascina lentamente e guarda l’anteprima. L’aggiornamento in tempo reale mostra esattamente come risponde l’immagine, così puoi fermarti nel punto in cui la foto sembra giusta.</p>\n<p>I piccoli spostamenti sono meglio di quelli grandi. Una variazione del 10-20% basta spesso, e spostamenti più grandi bruciano in fretta le luci e schiacciano le ombre.</p>\n<p>Lo strumento mostra la tua foto a +20% subito dopo il caricamento. Questo punto di partenza ti dà subito un’idea di come appare una spinta moderata di contrasto.</p>\n<h2 id=\"using-quick-presets\">Usare i preset rapidi</h2>\n<p>Lo strumento include preset rapidi che applicano valori comuni di contrasto in un solo clic. Sono un modo veloce per provare livelli diversi senza trascinare il cursore.</p>\n<p>Clicca un preset e guarda l’anteprima. Se il risultato è vicino ma non del tutto giusto, rifinisci con il cursore da quel punto.</p>\n<p>Usa i preset per confrontare le opzioni in fretta. Un preset a +10% accanto a uno a +30% ti mostra quanto contrasto la foto può sopportare.</p>\n<p>Per una serie di foto simili, lo stesso preset mantiene coerenti i risultati. Una serie di paesaggi nebbiosi, tutti potenziati dello stesso valore, sembra una serie vera.</p>\n<h2 id=\"using-compare-modes\">Usare le modalità di confronto</h2>\n<p>Le modalità di confronto mostrano l’originale e la versione modificata insieme. La vista Dopo mostra l’immagine con il contrasto aumentato, la vista Prima mostra l’originale.</p>\n<p>Il Confronto diviso è il più utile per lavorare sul contrasto. Mostra entrambe le versioni affiancate, così vedi esattamente quali ombre si sono approfondite e quali luci si sono schiarite.</p>\n<p>Il Confronto a schermo intero ti dà la vista più grande. È il modo migliore per giudicare una modifica di contrasto, perché l’immagine a dimensione intera mostra bruciature che una piccola anteprima nasconde.</p>\n<p>Controlla la vista di confronto prima di ogni download. Un’occhiata veloce rileva luci bruciate e ombre schiacciate che una piccola anteprima potrebbe nascondere.</p>\n<h2 id=\"boosting-a-flat-photo\">Dare forza a una foto piatta</h2>\n<p>Carica la foto piatta e trascina il cursore a +15%. Controlla l’anteprima: le ombre dovrebbero approfondirsi, le luci schiarirsi e l’immagine dovrebbe sembrare solida.</p>\n<p>Se la foto è ancora piatta, aumenta il cursore a piccoli passi del 5%. Ogni passo aggiunge un po’ di forza in più, e l’anteprima mostra quando fermarsi.</p>\n<p>Guarda le luci mentre procedi. Nuvole, camicie bianche e pelle chiara si bruciano per prime, diventando macchie bianche senza dettagli.</p>\n<p>Se dopo la spinta la foto sembra dura, abbassa il cursore del 5%. Una piccola riduzione spesso ripristina i dettagli senza rendere di nuovo piatta la foto.</p>\n<h2 id=\"softening-a-harsh-photo\">Ammorbidire una foto dura</h2>\n<p>Trascina il cursore a sinistra per una foto scattata con il sole forte di mezzogiorno. Valori negativi come −10% o −20% ammorbidiscono le ombre forti su un viso.</p>\n<p>Controlla il viso mentre ammorbidisci. Le ombre dovrebbero sfumare in un aspetto più delicato, mentre la forma generale del viso resta chiara e definita.</p>\n<p>Il contrasto negativo va bene anche per paesaggi sognanti e morbidi. Una scena mattutina con nebbia e poco contrasto sembra calma e silenziosa, e questo si abbina all’atmosfera della foto.</p>\n<p>Non esagerare. Una foto con troppo poco contrasto sembra grigia e senza vita, come se fosse stata scattata attraverso la nebbia, anche in una giornata limpida.</p>\n<h2 id=\"fixing-a-screenshot\">Sistemare uno screenshot spento</h2>\n<p>Incolla uno screenshot direttamente con Ctrl+V per saltare il passaggio del salvataggio. L’immagine compare subito nell’editor, pronta da regolare.</p>\n<p>Aumenta il contrasto finché il testo è scuro e lo sfondo è bianco. Un documento con un testo nero forte su uno sfondo bianco pulito è facile da leggere e da stampare.</p>\n<p>Fai attenzione al rumore nello sfondo. Una scansione con troppo contrasto può mostrare puntini e artefatti, soprattutto in un JPEG già compresso.</p>\n<p>Esporta gli screenshot in PNG. Il formato senza perdite mantiene nitido il testo piccolo, e questo conta quando lo screenshot mostra un’impostazione o un messaggio di errore.</p>\n<h2 id=\"checking-shadows-highlights\">Controllare ombre e luci</h2>\n<p>Dopo ogni modifica di contrasto, controlla separatamente le parti più scure e quelle più chiare dell’immagine. Le ombre si schiacciano per prime con una spinta, e le luci si bruciano per prime con la stessa mossa.</p>\n<p>Ingrandisci una zona d’ombra e conferma che mostri ancora dettagli. Un cappotto, un albero o un angolo scuro dovrebbero avere una texture visibile, non una macchia nera compatta.</p>\n<p>Ingrandisci una zona chiara e conferma che mostri ancora dettagli. Una nuvola, una camicia bianca o una fronte luminosa dovrebbero avere una forma visibile, non uno spazio bianco vuoto.</p>\n<p>Se uno dei due estremi ha perso dettagli, abbassa il cursore del 5% e controlla di nuovo. Piccole riduzioni di solito ripristinano i dettagli senza far perdere la forza.</p>\n<h2 id=\"previewing\">Controllare l’anteprima prima di scaricare</h2>\n<p>Controlla sempre l’anteprima prima di scaricare. Verifica che la foto sembri decisa, che nessuna zona chiara sia diventata bianca e che nessuna zona scura sia diventata nera.</p>\n<p>Usa la vista di confronto diviso per controllare la modifica. Mostra l’originale e la versione modificata affiancate, così vedi esattamente che cosa ha fatto il contrasto.</p>\n<p>Ingrandisci le zone chiare e scure a dimensione intera. Un cielo o un’ombra che in una piccola anteprima sembra a posto può risultare bruciato o schiacciato se visto in grande.</p>\n<p>Se il risultato sembra duro, abbassa il cursore del 5% e controlla di nuovo. Piccole riduzioni spesso ripristinano i dettagli senza rendere di nuovo piatta la foto.</p>\n<h2 id=\"choosing-export-format\">Scegliere il formato di esportazione</h2>\n<p>Scegli il JPG per le foto che vuoi condividere. Mantiene piccoli i file e funziona ovunque, e un’impostazione di alta qualità mantiene pulita la foto con il contrasto modificato.</p>\n<p>Scegli il PNG per screenshot e grafiche con testo. Il PNG è senza perdite, quindi i bordi delle lettere restano nitidi, e conserva la trasparenza quando serve.</p>\n<p>Scegli il WebP quando vuoi file piccoli con una buona qualità. Funziona bene per le immagini web, anche se alcuni sistemi più vecchi rifiutano ancora questo formato.</p>\n<p>Ricorda che il cursore della qualità si nasconde per il PNG, perché il PNG è senza perdite e non ha un’impostazione di qualità da regolare. È un comportamento normale, non un problema dello strumento.</p>\n<h2 id=\"adjusting-on-mobile\">Regolare il contrasto da telefono o tablet</h2>\n<p>Lo strumento funziona sui touchscreen, quindi puoi sistemare una foto piatta direttamente dal telefono che l’ha scattata. Caricala dalla galleria, trascina il cursore con il dito e scarica il risultato.</p>\n<p>Trascinare un cursore con il dito è meno preciso che con il mouse. Usa i preset rapidi per valori esatti, poi rifinisci con piccoli trascinamenti.</p>\n<p>Controlla l’anteprima a dimensione intera prima di scaricare. Una modifica di contrasto che sullo schermo piccolo del telefono sembra buona può risultare troppo forte se vista da un computer.</p>\n<p>I file scaricati finiscono nella solita cartella dei download. Da lì puoi condividere la foto modificata direttamente in un’app di chat, in un’email o in un post social.</p>\n<h2 id=\"troubleshooting\">Risolvere i problemi più comuni del contrasto</h2>\n<p>Se la foto sembra dura, il cursore è troppo alto. Abbassalo a piccoli passi finché pelle, cielo e zone d’ombra mostrano di nuovo la texture.</p>\n<p>Se dopo la spinta la foto è ancora piatta, l’originale potrebbe essere troppo nebbioso per essere salvato. Una foto scattata attraverso una nebbia fitta non può guadagnare dettagli che non sono mai stati catturati.</p>\n<p>Se le luci sono bruciate, abbassa il cursore e controlla le zone chiare a dimensione intera. Una piccola riduzione di solito ripristina i dettagli di nuvole o pelle.</p>\n<p>Se l’anteprima sembra diversa dal file scaricato, controlla il formato di esportazione e la qualità. Un’impostazione di bassa qualità JPG può ammorbidire l’intera immagine, compresi i bordi di contrasto.</p>\n<h2 id=\"contrast-plus-brightness\">Contrasto più luminosità: la coppia più comune</h2>\n<p>Una foto scura e piatta ha bisogno di luminosità e contrasto insieme. Schiarisci prima per alzare il livello generale, poi aggiungi contrasto per ripristinare la profondità.</p>\n<p>Usa lo strumento <a href=\"/it/regola-luminosita-immagine/\">Regola luminosità immagine</a> prima di aggiungere contrasto, quando l’immagine è scura. Una spinta di contrasto su una foto scura approfondisce solo le ombre.</p>\n<p>Fai i passaggi in ordine: prima la luminosità, poi il contrasto. Invertirli può rendere più difficile giudicare la regolazione del contrasto, perché l’immagine è ancora scura.</p>\n<p>Controlla la vista di confronto dopo ogni passaggio. La vista divisa mostra esattamente che cosa ha fatto ogni regolazione, così puoi fermarti quando la foto sembra giusta.</p>\n<h2 id=\"saving-settings\">Salvare le impostazioni per la prossima volta</h2>\n<p>Annota il valore di contrasto che ha funzionato per una serie di foto simili. Una breve nota, per esempio «paesaggi nebbiosi +20%», ti evita di indovinare la prossima volta.</p>\n<p>Per una serie di foto scattate con la stessa luce, usa lo stesso valore per tutte. Un contrasto coerente in una serie sembra professionale, mentre valori misti sembrano casuali.</p>\n<p>Conserva i file originali. Un valore di contrasto che va bene per una foto potrebbe non andare bene per un’altra, e l’originale ti permette di provare un altro livello senza danni aggiuntivi.</p>\n<p>Rileggi le tue note ogni tanto. Man mano che la tua fotocamera e la tua illuminazione migliorano, i valori di contrasto di cui hai bisogno cambieranno, e le vecchie note possono trarti in inganno.</p>\n<h2 id=\"quick-tips\">Consigli rapidi per un contrasto migliore</h2>\n<p>Regola a piccoli passi. Una variazione del 5% alla volta ti dà controllo, mentre un salto grande può superare il valore giusto prima che tu te ne accorga.</p>\n<p>Controlla gli estremi, non solo il centro. Una foto ha troppo contrasto quando le luci si bruciano o le ombre si schiacciano, anche se i toni medi sembrano buoni.</p>\n<p>Usa la vista di confronto ogni volta. Un’occhiata veloce all’originale accanto alla modifica rileva errori che una piccola anteprima nasconde.</p>\n<p>Salva la foto originale senza modifiche. Una volta che una modifica di contrasto è stata fissata in un’esportazione, non si può più annullare da quel file.</p>\n<h2 id=\"contrast-for-product-photo\">Aggiungere contrasto a una foto di prodotto</h2>\n<p>Le foto di prodotto hanno bisogno di un contrasto chiaro, così l’articolo spicca sullo sfondo. Una foto di prodotto piatta sembra spenta, mentre una decisa attira l’occhio sull’articolo.</p>\n<p>Usa una spinta moderata, del 10-20%, per quasi tutti i prodotti. L’articolo dovrebbe sembrare solido e definito, con bordi chiari contro lo sfondo.</p>\n<p>Guarda i colori del prodotto mentre aumenti il contrasto. Una spinta troppo forte può far sembrare duri i colori, quindi controlla l’articolo stesso, non solo lo sfondo.</p>\n<p>Mantieni lo stesso contrasto in tutto il catalogo. Un negozio con livelli di contrasto uguali sembra ordinato e affidabile, mentre livelli misti sembrano trascuratezza.</p>\n<p>Per il confronto, leggi <a href=\"/it/blog/luminosita-esposizione-contrasto-differenze/\">Luminosità, esposizione e contrasto: le basi del fotoritocco</a>. Per la panoramica completa, leggi <a href=\"/it/blog/come-regolare-contrasto-immagine-guida-completa/\">Regolare il contrasto di un’immagine: guida completa</a>. Per sistemare una foto scura prima di aggiungere contrasto, prova lo strumento <a href=\"/it/regola-luminosita-immagine/\">Regola luminosità immagine</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Come aggiungo contrasto a una foto dal telefono?","answer":"Apri lo strumento Regola contrasto immagine nel browser del telefono, carica la foto dalla galleria e trascina il cursore a destra con il dito. Usa un preset rapido per un valore esatto, controlla la vista di confronto e scarica il risultato."},{"question":"Quale valore di contrasto devo usare per un paesaggio nebbioso?","answer":"Parti da +15-20% e controlla il cielo. La foschia appiattisce la gamma tonale, quindi una spinta moderata ripristina la profondità. Fermati prima che le nuvole diventino spazi bianchi, e abbassa il cursore se le luci si bruciano."},{"question":"Posso ridurre il contrasto per ammorbidire un ritratto duro?","answer":"Sì. Trascina il cursore a sinistra, verso valori negativi, come −10% o −20%. Il contrasto negativo ammorbidisce le ombre forti sul viso senza fargli perdere la forma. Controlla la pelle, così resta definita e non diventa grigia."},{"question":"Perché le luci della mia foto diventano bianche dopo aver aggiunto contrasto?","answer":"Il contrasto è stato spinto troppo oltre, e questo brucia le zone più chiare fino al bianco puro. Abbassa il cursore a piccoli passi finché nuvole, pelle e superfici bianche mostrano di nuovo i dettagli. Una spinta del 10-20% di solito basta."},{"question":"Devo regolare il contrasto prima o dopo la luminosità?","answer":"Prima la luminosità, poi il contrasto. La luminosità imposta il livello generale, e il contrasto rifinisce l’estensione intorno a quel livello. Una foto scura ha bisogno di essere schiarita prima del contrasto, perché il contrasto da solo non può sistemare il livello."},{"question":"Posso annullare una modifica di contrasto dopo aver scaricato?","answer":"Non dal file scaricato, perché la modifica è fissata nell’esportazione. Conserva la foto originale, così puoi provare un altro livello di contrasto. Nello strumento, usa l’opzione di reset per tornare a zero prima di scaricare."}];
